    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (tid, '101. During CPR, what is the recommended compression rate for adults?', '["60-80 per minute", "100-120 per minute", "80-100 per minute", "120-140 per minute"]', 1, 'AHA 2020 guidelines recommend chest compressions at 100-120/min with a depth of at least 2 inches (5 cm) but not exceeding 2.4 inches (6 cm). Allow full chest recoil between compressions.'),
    (tid, '102. What is the recommended compression-to-ventilation ratio for a single rescuer performing CPR on an adult?', '["15:2", "30:2", "15:1", "Continuous compressions only"]', 1, 'Single rescuer adult CPR uses 30 compressions to 2 ventilations. With an advanced airway in place, continuous compressions at 100-120/min with 1 breath every 6 seconds (10 breaths/min) are given.'),
    (tid, '103. In the ACLS pulseless arrest algorithm, what are the two shockable rhythms?', '["Asystole and PEA", "Ventricular fibrillation and pulseless ventricular tachycardia", "Sinus bradycardia and complete heart block", "Atrial fibrillation and atrial flutter"]', 1, 'VF and pulseless VT are shockable rhythms treated with defibrillation. Asystole and PEA are non-shockable and are managed with CPR, epinephrine, and identifying reversible causes (Hs and Ts).'),
    (tid, '104. What are the reversible causes of cardiac arrest represented by the "Hs and Ts"?', '["Hs: Hypovolemia, Hypoxia, Hydrogen ion (acidosis), Hypo/Hyperkalemia, Hypothermia. Ts: Tension pneumothorax, Tamponade, Toxins, Thrombosis (PE/MI)", "Hs: Hypertension, Hypoglycemia. Ts: Trauma, Tachycardia", "Hs: Heart failure. Ts: Thyroid storm", "None of the above"]', 0, 'The Hs and Ts mnemonic ensures systematic identification of treatable causes during cardiac arrest. Addressing these causes is often the only way to achieve ROSC in PEA/asystole.'),
    (tid, '105. A patient in cardiac arrest has return of spontaneous circulation (ROSC). What is the target temperature for therapeutic hypothermia?', '["32-34°C for 24 hours", "32-36°C for at least 24 hours", "28-30°C for 12 hours", "Normal body temperature maintenance only"]', 1, 'TTM (targeted temperature management) at 32-36°C for at least 24 hours is recommended for comatose adults with ROSC after cardiac arrest to improve neurological outcomes. The TTM2 trial supports 36°C as equivalent.'),
    (tid, '106. After ROSC, what is the most common cause of early re-arrest?', '["Recurrent VF/VT", "Tension pneumothorax", "Hyperkalemia", "Hypovolemia"]', 0, 'Recurrent VF/VT is the most common cause of early re-arrest. Continuous cardiac monitoring, antiarrhythmic infusion (amiodarone), and correction of metabolic abnormalities are essential post-ROSC.'),
    (tid, '107. In PEA arrest, which clinical finding helps differentiate true PEA from pseudo-PEA?', '["Pupil reactivity", "Bedside ultrasound showing cardiac wall motion", "Capnography reading", "Pulse oximetry waveform"]', 1, 'Point-of-care ultrasound during pulse checks can identify cardiac wall motion (pseudo-PEA with weak contractions) versus true PEA (no wall motion). Pseudo-PEA has a better prognosis and may respond to vasopressors.'),
    (tid, '108. What does an end-tidal CO2 (ETCO2) value of less than 10 mmHg during CPR indicate?', '["Effective chest compressions", "Poor quality CPR or low cardiac output", "Hyperventilation", "Return of spontaneous circulation"]', 1, 'ETCO2 <10 mmHg during CPR indicates poor perfusion from inadequate compressions or severe cardiac dysfunction. ETCO2 >20 mmHg correlates with better outcomes. A sudden rise in ETCO2 may signal ROSC.'),
    (tid, '109. A patient is found in asystole. After confirming in two leads, what is the next step?', '["Defibrillation at 200J", "CPR, epinephrine 1mg IV, and search for reversible causes", "Transcutaneous pacing", "Procainamide infusion"]', 1, 'Asystole is a non-shockable rhythm. Defibrillation is not indicated. Management includes high-quality CPR, epinephrine every 3-5 min, and aggressive search for reversible causes (Hs and Ts).'),
    (tid, '110. During ACLS, when should the rhythm be checked?', '["Every 1 minute", "Every 2 minutes (after each cycle of CPR)", "Every 5 minutes", "Only when ETCO2 changes"]', 1, 'Rhythm checks occur every 2 minutes, coinciding with compressor switches to minimize interruptions. Pulse checks should be brief (<10 seconds). Minimize pauses in compressions.'),
    (tid, '111. What is the role of vasopressin in the current ACLS algorithm?', '["First-line instead of epinephrine", "It is no longer recommended as a substitute for epinephrine", "Only for PEA arrest", "Combined with amiodarone for VF"]', 1, 'AHA 2020 removed vasopressin as an alternative to epinephrine because it showed no survival benefit over epinephrine alone. Epinephrine 1mg IV/IO every 3-5 min remains the standard.'),
    (tid, '112. A drowning victim is pulled from cold water (estimated submersion 25 minutes). Core temperature is 28°C. There is no pulse. What is the appropriate action?', '["Pronounce dead due to prolonged submersion", "Begin CPR and rewarm; do not withhold resuscitation until core temp >32°C", "Defibrillate three times then stop", "Start IV fluids only"]', 1, 'Hypothermic patients should not be pronounced dead until they are warm and dead. CPR should continue with active rewarming. Defibrillation may be ineffective below 30°C; limit to one attempt until rewarmed.'),
    (tid, '113. In a witnessed cardiac arrest with shockable rhythm, what single intervention has the greatest impact on survival?', '["IV epinephrine", "Early defibrillation", "Endotracheal intubation", "IV amiodarone"]', 1, 'Early defibrillation is the single most important intervention for VF/pulseless VT. Survival decreases 7-10% for every minute defibrillation is delayed. This is why AEDs in public spaces save lives.'),
    (tid, '114. What medication is recommended for post-ROSC hypotension refractory to IV fluids?', '["Norepinephrine or epinephrine infusion", "IV phenylephrine bolus", "Oral midodrine", "IV calcium chloride"]', 0, 'Post-ROSC hypotension (MAP <65) refractory to fluids should be treated with vasopressor infusion (norepinephrine preferred) to maintain adequate coronary and cerebral perfusion.'),
    (tid, '115. A patient with ROSC after cardiac arrest remains comatose. What is the earliest reliable time for neurological prognostication?', '["Immediately after ROSC", "6 hours", "72 hours after achieving normothermia", "1 week"]', 2, 'AHA recommends waiting at least 72 hours after return to normothermia before prognostication. Earlier assessment is unreliable due to residual sedation, hypothermia, and metabolic derangements.'),
    (tid, '116. Which post-ROSC intervention has been shown to improve outcomes when a cardiac etiology is suspected?', '["CT head scan", "Emergent coronary angiography", "Lumbar puncture", "Chest X-ray"]', 1, 'Emergent coronary angiography (and PCI if indicated) is recommended for post-cardiac arrest patients with suspected cardiac etiology, especially with STEMI on ECG, regardless of consciousness level.'),
    (tid, '117. During cardiac arrest in a pregnant patient at 32 weeks, when should perimortem cesarean delivery be initiated?', '["After 20 minutes of failed CPR", "Within 4-5 minutes if no ROSC", "Only after consulting obstetrics", "Perimortem C-section is contraindicated"]', 1, 'Perimortem C-section should begin within 4 minutes of cardiac arrest with delivery by 5 minutes. Relieving aortocaval compression improves maternal resuscitation and fetal survival.'),
    (tid, '118. During CPR on a pregnant patient, what modification is essential?', '["No modifications needed", "Left uterine displacement to relieve aortocaval compression", "Compressions at a lower rate", "Avoid defibrillation"]', 1, 'The gravid uterus compresses the IVC and aorta in the supine position. Manual left uterine displacement (or left lateral tilt of 15-30°) is essential to improve venous return and cardiac output during CPR.'),
    (tid, '119. What is the recommended first-line airway management during cardiac arrest according to AHA 2020?', '["Immediate endotracheal intubation", "Bag-valve-mask ventilation or supraglottic airway", "Cricothyrotomy", "Nasopharyngeal airway only"]', 1, 'AHA 2020 recommends BVM or supraglottic airway (LMA, King) as initial airway management during cardiac arrest. ETI should not delay compressions and shows no survival benefit over SGA in out-of-hospital arrest.'),
    (tid, '120. What is the significance of a sudden rise in ETCO2 from 12 to 40 mmHg during CPR?', '["Equipment malfunction", "Likely return of spontaneous circulation (ROSC)", "Esophageal intubation", "Hyperventilation"]', 1, 'A sudden sustained rise in ETCO2 (typically >40 mmHg) during CPR strongly suggests ROSC as the restored circulation delivers CO2-rich blood to the lungs. This should prompt a pulse check.'),
    (tid, '121. In opioid-associated cardiac arrest, what medication should be administered in addition to standard ACLS?', '["Flumazenil", "Naloxone 2mg IV/IM/IN", "N-acetylcysteine", "Activated charcoal"]', 1, 'Naloxone is an opioid antagonist that should be given in suspected opioid-associated cardiac arrest. It may reverse respiratory depression that precipitated the arrest. Standard ACLS takes priority.'),
    (tid, '122. A patient in cardiac arrest has a potassium level of 7.8 mEq/L. In addition to standard ACLS, what specific treatment should be given?', '["IV calcium chloride, IV sodium bicarbonate, IV insulin with dextrose", "IV magnesium only", "Oral kayexalate", "Dialysis during CPR"]', 0, 'Hyperkalemic cardiac arrest requires IV calcium for membrane stabilization, sodium bicarbonate to shift K+ intracellularly, and insulin/dextrose for further K+ shifting, all given during ongoing CPR.'),
    (tid, '123. What is the recommended depth of chest compressions in adult CPR?', '["1 inch (2.5 cm)", "At least 2 inches (5 cm) but no more than 2.4 inches (6 cm)", "3 inches (7.5 cm)", "Depth does not matter if rate is correct"]', 1, 'AHA 2020 specifies compression depth of at least 2 inches (5 cm) but not more than 2.4 inches (6 cm). Excessive depth increases risk of injury; insufficient depth reduces coronary perfusion pressure.'),
    (tid, '124. In which scenario should CPR be withheld or terminated in the field?', '["Rigor mortis, dependent lividity, or obvious signs of death", "Age over 85 years", "Unwitnessed arrest of unknown duration", "Initial rhythm of asystole"]', 0, 'CPR should be withheld only when there are obvious signs of irreversible death: rigor mortis, dependent lividity (livor mortis), decomposition, or injuries incompatible with life (decapitation).'),
    (tid, '125. What is the role of mechanical CPR devices (LUCAS, AutoPulse) according to current guidelines?', '["Superior to manual CPR in all settings", "Reasonable alternative to high-quality manual CPR in specific settings (transport, prolonged resuscitation)", "Contraindicated in all patients", "Only for pediatric patients"]', 1, 'Mechanical CPR devices are a reasonable alternative when sustained high-quality manual CPR is not feasible (during transport, in cath lab, prolonged codes). They are not superior to well-performed manual CPR.');
